import{_ as o}from"./chunks/en_seznam_staveb.3uk_YXXA.js";import{_ as i,o as a,c as n,j as e,a as r,aa as s}from"./chunks/framework.BAs_AphD.js";const c="/buildary-help-preview/media/en/diary/en_vybratstavbu.jpg",l="/buildary-help-preview/media/en/diary/en_nova_stavba.jpg",d="/buildary-help-preview/media/en/diary/en_mapycz.jpg",h="/buildary-help-preview/media/en/diary/en_kopirovani_stavby.jpg",p="/buildary-help-preview/media/en/diary/en_nastavenistavby.jpg",m="/buildary-help-preview/media/en/diary/en_ares_.jpg",u="/buildary-help-preview/media/en/diary/en_clen_projektu.jpg",g="/buildary-help-preview/media/en/diary/en_roleclenu.jpg",f="/buildary-help-preview/media/en/diary/en_casti_stavby.jpg",y="/buildary-help-preview/media/en/diary/en_nova_cast_stavby.jpg",b="/buildary-help-preview/media/en/diary/en_ciselnik_osoby.jpg",w="/buildary-help-preview/media/en/diary/en_vytvoritvzor.jpg",j="/buildary-help-preview/media/en/diary/en_pouzitvzor.jpg",S=JSON.parse('{"title":"Creating a Project and Its Participants","description":"","frontmatter":{"title":"Creating a Project and Its Participants","wiki":"en:diary:projectsetup"},"headers":[],"relativePath":"en/diary/projectsetup.md","filePath":"en/diary/projectsetup.md","lastUpdated":1794388980000}'),P={name:"en/diary/projectsetup.md"};function v(T,t,k,_,C,x){return a(),n("div",null,[...t[0]||(t[0]=[e("h1",{id:"creating-a-project-and-its-participants",tabindex:"-1"},[r("Creating a Project and Its Participants "),e("a",{class:"header-anchor",href:"#creating-a-project-and-its-participants","aria-label":'Permalink to "Creating a Project and Its Participants"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/_RrM5TPoGDM",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),s('<p>To create a project, the user must be a member of a domain and have the appropriate permissions assigned. To edit the settings of an existing project, the user must have the permissions associated with their role in the project. In a personal domain, the user automatically has all permissions. For more information, see <a href="/buildary-help-preview/en/diary/userpermissions">User Permissions</a>.</p><h2 id="creating-a-project" tabindex="-1">Creating a Project <a class="header-anchor" href="#creating-a-project" aria-label="Permalink to &quot;Creating a Project&quot;">​</a></h2><figure class="shot" style="--w:200px;"><img src="'+c+'" alt="" width="200" loading="lazy"></figure><p>A new project is created in the Project List window. You can access the project list using the <strong>Project List</strong> icon in the left panel.</p><figure class="shot" style="--w:600px;"><img src="'+o+'" alt="Open Construction Site window" width="600" loading="lazy"></figure><p>Create a new project by clicking the <strong>+ New Project</strong> button at the top.</p><figure class="shot" style="--w:600px;"><img src="'+l+'" alt="New Construction Site window" width="600" loading="lazy"></figure><p><strong>Project Image</strong> - insert a characteristic image that will help you distinguish the project in the project list. The recommended dimensions are 320x320 pixels, but the image will also be partially adapted if it has different dimensions.</p><p><strong>Project Name</strong> – the full name of the project according to the building permit.</p><p><strong>Project Short Name</strong> - the name used wherever the full name would be too long, e.g. on a mobile device, when generating file names, etc.</p><p><strong>Domain</strong> - when creating a project, you need to select the domain to which the project belongs. Please note! If you are an employee of a company, you may not have the permissions required to create a project in its domain. In such a case, contact the administrator of the company domain so that they can either grant you the necessary permissions or create the project themselves.</p><p><strong>Language</strong> - the language of the project/construction site, i.e. the language in which the project&#39;s code lists, diary sections, etc. will be generated. This operation cannot be reversed after the project has been created. If you need to change the language, the code lists can be rewritten manually, or a new project can be created in another language version.</p><p><strong>Project Templates</strong> - If the Domain Administrator has created Project Template, you can select which one you want to use. All predefined code lists and configurations for the project, diaries, and other modules will then be copied from the template.</p><p><strong>Project Start and End</strong> - the contractual start and end dates of the project.</p><figure class="shot" style="--w:600px;"><img src="'+d+'" alt="Finding Coordinates on the Map" width="600" loading="lazy"></figure><p><strong>Project Location</strong> - a textual description of the Project location.</p><p><strong>Project GPS Coordinates</strong> – placing the marker on the map automatically enters the Project coordinates. This information is required for communication with the server regarding weather data.</p><p><strong>Project Time Zone</strong> – the default time zone setting is suitable for projects in the Czech Republic and Slovakia. If you are building outside this area, select the appropriate time zone. This information is required for communication with the server regarding weather data.</p><p><strong>Modules Used</strong> - you can select which Buildary.online modules you want to use on the Project. This applies to projects added to domains operating in Standard mode (see Domain and Billing System). For Project in domains operating in Individual mode, the user cannot change this setting. It is predefined at the domain level. <strong>The module settings also affect the cost of using the Buildary service for the given Project.</strong> You can change the module settings at any time while working on the Project. An invoice for usage up to the date of the change will be calculated as of the date of the change. After that date, billing will be based on the new settings. For this reason, changing the settings more than once on the same day is not permitted.</p><p><strong>Project with Single Diary</strong> - this option is selected by default and means that the diary will be created automatically. If you expect to use multiple diaries on the Project (e.g. subcontractor, subproject, or other diaries), deselect this option so that you can create diaries in the Project as needed.</p><p><strong>Project Template</strong> - this option is available only to the Domain Administrator. It allows them to mark the Project being created as a Template. It can then be configured as required.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When the map is opened, the application will attempt to determine your current location, so you may be asked whether you want to allow location information to be shared. Click on the map to place the cursor at the construction site location. Confirm the location by clicking OK and transfer the coordinates to the application.</p></div><h2 id="creating-a-project-by-copying-an-existing-one" tabindex="-1">Creating a Project by Copying an Existing One <a class="header-anchor" href="#creating-a-project-by-copying-an-existing-one" aria-label="Permalink to &quot;Creating a Project by Copying an Existing One&quot;">​</a></h2><figure class="shot" style="--w:620px;"><img src="'+h+'" alt="Creating a New Construction Site by Copying an Existing One" width="600" loading="lazy"></figure><p>If you are creating a Project with properties similar to another Project in the relevant domain, you can use the <strong>New Project by Copy</strong> function. This function is available from the <strong>Project Settings</strong> of the Project you want to copy, via the three-dot menu.</p><p>After entering the name of the new project site, a new project is created that inherits the following from the original project:</p><ul><li>Project Information</li><li>Project Team</li><li>Code List - Project Diary</li><li>Code List - Ticket Management</li></ul><h2 id="project-configuration" tabindex="-1">Project Configuration <a class="header-anchor" href="#project-configuration" aria-label="Permalink to &quot;Project Configuration&quot;">​</a></h2><p>After creating the project, you need to create its project team. You can also divide the project into sections and upload drawings, which can then be used in the Project Diary module to locate Works Performed or Other Entries, and/or in the Ticket Management module to locate tickets. It is also possible to import or create lists for the Labour, Plants, and Materials sections.</p><p>These operations are performed in <strong>Project Settings</strong>, which can be accessed in 4 possible ways:</p><ul><li>from the Project List by clicking the edit icon (pencil) at the end of the row of the selected project</li><li>if the required project is expanded in the left panel, by clicking the <strong>project image</strong>, the <strong>project name</strong> below the image, or the <strong>gear icon</strong> (Project Settings) below the project name</li></ul><h2 id="project-team" tabindex="-1">Project Team <a class="header-anchor" href="#project-team" aria-label="Permalink to &quot;Project Team&quot;">​</a></h2><p>The <strong>Project Team</strong> tab contains identification details for all companies and authorized persons on the construction site. For clarity, the information is divided into sub-tabs. When entering items, we recommend starting with the Companies sub-tab, or Company Roles, and only then entering individual Project Members.</p><h3 id="companies" tabindex="-1">Companies <a class="header-anchor" href="#companies" aria-label="Permalink to &quot;Companies&quot;">​</a></h3><p>The <strong>Companies</strong> sub-tab contains all companies participating in the project. The first company record in the list is always automatically populated with the company from the domain.</p><figure class="shot" style="--w:600px;"><img src="'+p+'" alt="Construction Site Settings window" width="600" loading="lazy"></figure><p>Add additional companies using the <strong>+ Add</strong> button.</p><p>In the window for adding a new company, enter the company name, Company ID (IČO), and other company details. You also select a Company Role from the predefined list. This field is mandatory. The list of company roles can be modified in advance as needed.</p><figure class="shot" style="--w:400px;"><img src="'+m+'" alt="" width="400" loading="lazy"></figure><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For projects in the Czech Republic, after entering the company name or Company ID, you can click the <strong>ARES</strong> icon to automatically populate the available company information from the ARES register of the Czech Ministry of Finance. This functionality significantly simplifies your work, ensures that all information is completed, and prevents errors caused by incorrectly entered data:</p></div><h3 id="company-roles" tabindex="-1">Company Roles <a class="header-anchor" href="#company-roles" aria-label="Permalink to &quot;Company Roles&quot;">​</a></h3><p>This code list contains predefined roles most commonly used by companies on a project. You can extend the list with additional roles or rename existing roles.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you rename the default roles listed in the code list, make sure that the meaning of the role does not change. If in doubt, it is better to create a new role rather than rename an existing one incorrectly.</p></div><h3 id="project-team-member" tabindex="-1">Project Team Member <a class="header-anchor" href="#project-team-member" aria-label="Permalink to &quot;Project Team Member&quot;">​</a></h3><p>The <strong>Project Team Member</strong> sub-tab contains a list of people who form the project team (authorized persons). Each person should be assigned to a specific company.</p><figure class="shot" style="--w:600px;"><img src="'+u+'" alt="Project Member Form" width="600" loading="lazy"></figure><p>You can add new members using the <strong>+ Add</strong> button.</p><p>The meaning of the <strong>E-mail, First Name, Last Name, Phone</strong> fields is self-explanatory. If the user already has a Buildary account, entering the correct e-mail address will automatically populate the other information from the user account.</p><p><strong>Default Role</strong> - this role defines the user&#39;s permissions on the given construction site. In the Project Diary, a different role can be assigned to the user among the Authorized Persons of a specific diary.</p><p><strong>Validity</strong> - this date determines how long the user is allowed access to the construction site as a member of the project team. After this date, the user loses access.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For billing purposes, all users added to the project team are counted, including those whose validity has expired. Therefore, ending users&#39; validity and removing their access does not save you any money.</p></div><p><strong>E-mail Notifications</strong> - for individual modules, you can set whether the user should receive notifications. Where multiple options are available, you can also select the notification method.</p><p>After a new project team member is added, an invitation is sent to their e-mail address. The invitation contains both a link to the application for already registered users and a link to the registration form for new users. From this point onward, the user has access to the given construction site. However, access to the construction site does not yet grant access to the Project Diary. The user must be added to the diary as an authorized person. Only if the construction site has the <strong>Construction Site with One Diary</strong> option enabled will the newly added project team member also be automatically added to the diary&#39;s list of authorized persons.</p><p><strong>E-mail Notifications - Project Diary</strong> - In the settings for individual users, several options are available for sending Project Diary notifications when a record is added in the &quot;Other Entries&quot; section:</p><ul><li><p><strong>None</strong> – no notification is sent (this setting is defined at the construction site project team level by default and can no longer be changed in the identification details).</p></li><li><p><strong>HTML email</strong> – a notification is always sent when an Other Entry is added/edited (this setting is defined at the construction site project team level by default and can no longer be changed in the identification details).</p></li><li><p><strong>According to Diary Settings</strong> – after selecting this option at the construction site level, the identification details of individual diaries can be used to further specify which diary or diaries will send HTML notification emails. (This option is mainly intended for construction sites with more than one diary where notifications need to be sent only from a specific diary or specific diaries.)</p></li></ul><p><strong>E-mail Notifications - Construction Site Closure</strong></p><ul><li><p><strong>None</strong> – no notification is sent.</p></li><li><p><strong>HTML email</strong> – when the construction site is closed, the user will receive an e-mail notification.</p></li></ul><p><strong>E-mail Notifications - Ticket Management</strong> - see the description in the &quot;Ticket Management&quot; module under <a href="/buildary-help-preview/en/tickets/notification">Notifications</a>.</p><p><strong>E-mail Notifications - Performed Works</strong> - see the description in the &quot;Performed Works&quot; module under <a href="/buildary-help-preview/en/performedworks/competences">Competence Settings</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If the user is in the same domain as the construction site, they receive permissions on the construction site based on the permissions assigned to them at the domain level.</p></div><h3 id="member-roles" tabindex="-1">Member Roles <a class="header-anchor" href="#member-roles" aria-label="Permalink to &quot;Member Roles&quot;">​</a></h3><figure class="shot" style="--w:600px;"><img src="'+g+'" alt="Project Settings window" width="600" loading="lazy"></figure><p>This window contains a list of roles for people on the project. The permissions associated with each role are defined here as well.</p><p>You can create custom roles or edit the default roles. We recommend renaming default roles only when the change is purely formal and does not alter the meaning of the role.</p><p>The meaning of the individual permission categories is described in detail in the separate User Permissions section.</p><h2 id="project-sections-and-plans" tabindex="-1">Project Sections and Plans <a class="header-anchor" href="#project-sections-and-plans" aria-label="Permalink to &quot;Project Sections and Plans&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+f+'" alt="Project Sections and Plans Code List" width="600" loading="lazy"></figure><p>In this code list, you can define the hierarchical structure of the construction site. Click the <strong>+</strong> button to add another subordinate level below the currently selected section. At the first level, we recommend structuring the construction site according to building objects. Building objects can then be divided into more detailed sections if required. A suitable project structure significantly simplifies ticket localization.</p><p>Each section has an icon on the right showing the number of plans it contains.</p><figure class="shot" style="--w:600px;"><img src="'+y+'" alt="New Project Section and Plans" width="600" loading="lazy"></figure><p>One or more plans can be added to each section. You can add plans to the project section window individually, drag and drop multiple plans at once, or select multiple plans and upload them. Plans will be uploaded and sorted according to their file names.v</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Plans can be uploaded in PDF format or as images (JPG, PNG, etc.).</p></div><p>Before uploading a plan, you can rotate it to achieve the <strong>correct orientation</strong>. If you do not do this and the orientation is incorrect, you need to delete the plan before its first use and upload it again with the correct rotation.</p><p>If you want a different plan to be offered as the default plan for a given section instead of the first plan in alphabetical order, mark it as <strong>set plan as default</strong> using the icon with the plan and marker. The plan will then be placed first regardless of its file name.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Uploading plans is a time-consuming operation. A plan is not only uploaded but also divided into tiles so that subsequent work with it is fast. If you are uploading plans to multiple sections, we recommend opening the application in multiple windows and uploading the plans in parallel. This will significantly speed up the process.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Plans that have already been used in one of the entries or tickets cannot be deleted. They can only be deactivated so that they are no longer offered for selection.</p></div><h2 id="code-lists-project-diary" tabindex="-1">Code Lists - Project Diary <a class="header-anchor" href="#code-lists-project-diary" aria-label="Permalink to &quot;Code Lists - Project Diary&quot;">​</a></h2><p>These code lists apply only to the Project Diary module and can be prepared in advance for the project.</p><h3 id="categories-of-other-entries" tabindex="-1">Categories of Other Entries <a class="header-anchor" href="#categories-of-other-entries" aria-label="Permalink to &quot;Categories of Other Entries&quot;">​</a></h3><p>This code list is used to categorize entries in the Other Entries section and is predefined. The Project Administrator can edit the code list according to the needs of the given project. If the construction site was created using a Template Construction Site, the code list is copied from the template.</p><h3 id="labour-plants-and-materials" tabindex="-1">Labour, Plants and Materials <a class="header-anchor" href="#labour-plants-and-materials" aria-label="Permalink to &quot;Labour, Plants and Materials&quot;">​</a></h3><p>If you populate these code lists, their contents will be suggested when creating an entry in the relevant section. The lists can be created either by adding individual items using the <strong>+ Add</strong> button or by importing an entire list from an XLS file. To import an XLS list, the list must be on the first worksheet and must contain the exact column names. Hovering the mouse over the import button displays a tooltip with the required column names for each section. For people, for example: Name, Profession, Contractor.</p><img src="'+b+'" alt="Project Settings window" width="600" loading="lazy"><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Using code lists is not mandatory. They are simply an additional source of suggestions. Whether or not you use code lists, you can still enter data freely in the diary, and once an entry has been entered, it will be suggested the next time.</p></div><h2 id="project-template" tabindex="-1">Project Template <a class="header-anchor" href="#project-template" aria-label="Permalink to &quot;Project Template&quot;">​</a></h2><figure class="shot" style="--w:400px;"><img src="'+w+'" alt="" width="400" loading="lazy"></figure><p>An excellent tool for users who manage a larger number of projects and are not completely satisfied with the default settings. To avoid having the Administrator repeatedly make similar changes to code lists or diary settings, they can create one or more construction sites and mark them using the <strong>Create Template Construction Site</strong> checkbox. Data from the Project Template takes precedence over the default code lists and settings.</p><p><strong>The following can be predefined in a Project Template:</strong></p><ul><li>Project (Project Information) - modules used and the Project with single Diary switch</li><li>Project Team</li><li>Code Lists - Project Diary</li><li>Code Lists - Ticket Management</li></ul><figure class="shot" style="--w:600px;"><img src="'+j+'" alt="Use Template Construction Site" width="600" loading="lazy"></figure><p>When creating a new project, you can select <strong>Project Templates</strong> after selecting the domain and then choose the appropriate Project Template from the list.</p>',91)])])}const N=i(P,[["render",v]]);export{S as __pageData,N as default};
